prelude:
template <class A, class B> constexpr bool same = false;
template <class A> constexpr bool same<A, A> = true;
struct Done {};
struct Count { int n;
  struct It { int i, n; constexpr int operator*() const { return i; }
    constexpr It& operator++() { ++i; return *this; }
    constexpr bool operator==(Done) const { return i == n; } };
  constexpr It begin() const { return {0, n}; }
  constexpr Done end() const { return {}; } };

